// Generated by OSL (@osl/backend-hono-trpc-vite). Email: logged to the console, sent through Resend, or captured in memory for tests.
// Do not edit: this file is rewritten on every osl generate.

export type Email = { to: string; subject: string; text: string; html?: string };
export type EmailMode = "log" | "resend" | "capture";

// OSL_EMAIL=log|resend|capture; without it, resend when RESEND_API_KEY is set, else log.
// capture keeps emails in memory and lets sign-in responses carry their tokens: only for tests.
const mode: EmailMode = (process.env.OSL_EMAIL as EmailMode | undefined) ?? (process.env.RESEND_API_KEY ? "resend" : "log");
const from = process.env.EMAIL_FROM ?? "no-reply@example.com";

export function emailMode(): EmailMode {
  return mode;
}

/** Emails sent while capturing, newest last */
export const captured: Email[] = [];

export async function sendEmail(email: Email): Promise<void> {
  switch (mode) {
    case "capture":
      captured.push(email);
      return;
    case "log":
      console.log("[email] to " + email.to + ": " + email.subject + "\n" + email.text);
      return;
    case "resend": {
      const response = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: { authorization: "Bearer " + process.env.RESEND_API_KEY, "content-type": "application/json" },
        body: JSON.stringify({ from, to: [email.to], subject: email.subject, text: email.text, html: email.html })
      });
      if (!response.ok) throw new Error("Resend answered " + response.status + ": " + (await response.text()));
    }
  }
}

/** The mail an invite sends: who invites, to what, as what, the link, and the day the link stops working */
export function inviteEmail(invite: { to: string; name: string; inviter: string; role?: string | null; url: string; expires: Date }): Email {
  return {
    to: invite.to,
    subject: "You are invited to " + invite.name,
    text:
      (invite.inviter || "Someone") + " invited you to " + invite.name + (invite.role ? " as " + invite.role : "") + ".\n\n" +
      "Accept the invite: " + invite.url + "\n\n" +
      "The link works until " + invite.expires.toISOString().slice(0, 10) + "."
  };
}
